function publicUser(user: StoredUser) { return { id: user.id, email: user.email, name: user.name, roles: user.roles, createdAt: user.createdAt.toISOString(), updatedAt: user.updatedAt.toISOString() }; }
function maskPhone(phone: string | null): string | null { if (!phone) return null; if (phone.length <= 4) return "*".repeat(phone.length); return `${phone.slice(0, 2)}${"*".repeat(Math.max(1, phone.length - 5))}${phone.slice(-2)}`; }
