const SECRET_KEYS = new Set(["password", "passwordHash", "token", "refreshToken", "accessToken", "session", "sessionString", "encryptedArchive", "encryptedUsername", "encryptedPassword", "apiHash", "apiKey", "secret"]);
function redact(value: unknown): unknown { if (Array.isArray(value)) return value.map(redact); if (value && typeof value === "object") { const output: Record<string, unknown> = {}; for (const [key, child] of Object.entries(value)) output[key] = SECRET_KEYS.has(key) ? "[REDACTED]" : redact(child); return output; } return value; }
